// Code node do n8n — normaliza a resposta da IA para { email, subject, text_body, html_body }
// Sem alterar o conteúdo gerado pela IA (nenhum trim/reescrita nos valores)

// 1) Remove cercas markdown
//json  e texto ao redor
const extrairJson = (texto) => {
  let t = (texto ?? '').replace(/^(?:json)?\s*/i, '').replace(/\s*$/, '');
  const inicio = t.indexOf('{');
  const fim = t.lastIndexOf('}');
  try {
    return JSON.parse(t.slice(inicio, fim + 1));
  } catch (e) {
    return null;
  }
};

// 2) Recupera o texto bruto de qualquer formato de chegada e extrai o JSON
const normalizarFonte = (fonte) => {
  if (Array.isArray(fonte)) return fonte.flatMap(normalizarFonte);
  if (typeof fonte === 'string') {
    const parsed = extrairJson(fonte);
    return parsed ? [parsed] : [];
  }
  if (fonte && typeof fonte === 'object') {
    // Estrutura do anexo: { content: { parts: [{ text: "..." }] } }
    if (fonte.content?.parts?.[0]?.text) return normalizarFonte(fonte.content.parts[0].text);
    if (typeof fonte.text === 'string') return normalizarFonte(fonte.text);
    // Saídas comuns de nós de IA: output / message.content
    if (fonte.output !== undefined) return normalizarFonte(fonte.output);
    if (typeof fonte.message?.content === 'string') return normalizarFonte(fonte.message.content);
    // Já veio normalizado
    if (fonte.email !== undefined) return [fonte];
  }
  return [];
};

// 3) Extrai os 4 campos exatamente como a IA escreveu
const saida = [];
for (const item of items) {
  for (const emailObj of normalizarFonte(item.json)) {
    saida.push({
      json: {
        email: emailObj.email,
        subject: emailObj.subject,
        text_body: emailObj.text_body,
        html_body: emailObj.html_body
      }
    });
  }
}

return saida;
